import{_ as a,o as t,c as i,ae as n}from"./chunks/framework.1Lna8NcP.js";const h=JSON.parse('{"title":"ADR-002 — Data Ingestion Strategy: Multi-Source Support","description":"","frontmatter":{},"headers":[],"relativePath":"adr/002-data-ingestion-strategy.md","filePath":"adr/002-data-ingestion-strategy.md"}'),r={name:"adr/002-data-ingestion-strategy.md"};function o(l,e,s,d,c,u){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="adr-002-—-data-ingestion-strategy-multi-source-support" tabindex="-1">ADR-002 — Data Ingestion Strategy: Multi-Source Support <a class="header-anchor" href="#adr-002-—-data-ingestion-strategy-multi-source-support" aria-label="Permalink to &quot;ADR-002 — Data Ingestion Strategy: Multi-Source Support&quot;">​</a></h1><p><strong>Status: Accepted | 2026-04-11</strong></p><hr><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>ADR-001 established CSV/Excel file import as the sole data ingestion method, citing privacy as a first-class feature:</p><blockquote><p><em>&quot;CSV/Excel import only — no direct institution API links (privacy trade-off, intentional)&quot;</em></p></blockquote><p>This was the right call for the initial prototype. However, as Libertas evolves toward a genuine financial freedom planning tool, the friction of manual CSV exports has become a real barrier to usefulness:</p><ul><li>Users won&#39;t maintain accurate data if the update flow is tedious</li><li>Debt balances and cash accounts are especially painful to track via CSV exports</li><li>Manual entry for simple values (salary, savings balance) shouldn&#39;t require a file at all</li><li>Real-time accuracy matters for FIRE planning — stale data produces wrong retirement projections</li></ul><p>The goal is to support all three data paths, with privacy preserved as a default and any third-party connectivity remaining <strong>explicitly opt-in</strong>.</p><hr><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>Libertas will support three data ingestion methods, ordered by friction (lowest to highest):</p><h3 id="_1-manual-user-input-new" tabindex="-1">1. Manual User Input (new) <a class="header-anchor" href="#_1-manual-user-input-new" aria-label="Permalink to &quot;1. Manual User Input (new)&quot;">​</a></h3><p>Direct in-app entry for any financial value: account balances, debt balances, income, expenses. No file, no external service. The baseline that works on day one for any user.</p><ul><li>Always available, always free</li><li>Best for: cash accounts, informal debt, income, one-off values</li><li>Stored directly in SQLite</li></ul><h3 id="_2-csv-excel-file-import-existing-from-adr-001" tabindex="-1">2. CSV / Excel File Import (existing, from ADR-001) <a class="header-anchor" href="#_2-csv-excel-file-import-existing-from-adr-001" aria-label="Permalink to &quot;2. CSV / Excel File Import (existing, from ADR-001)&quot;">​</a></h3><p>Preserved as-is. Watch folder + column mapping + institution presets remain core. No change to existing behavior.</p><ul><li>Best for: brokerage exports (Fidelity, Schwab, Robinhood), crypto (Coinbase), bank statement history</li><li>Still the most privacy-preserving path for transaction history</li></ul><h3 id="_3-plaid-integration-new-opt-in" tabindex="-1">3. Plaid Integration (new, opt-in) <a class="header-anchor" href="#_3-plaid-integration-new-opt-in" aria-label="Permalink to &quot;3. Plaid Integration (new, opt-in)&quot;">​</a></h3><p>Real-time bank account, credit card, and liability sync via Plaid (or a free alternative — see below). Requires explicit user opt-in and credential setup. Never enabled by default.</p><ul><li>Best for: live balance sync, credit card tracking, debt liabilities (student loans, auto, mortgage)</li><li>User controls connection; credentials are stored locally (Plaid access tokens in SQLite, never sent to Libertas servers — there are none)</li><li><strong>Cost constraint:</strong> Plaid&#39;s production pricing is non-trivial. Free alternatives must be evaluated first (SimpleFIN Bridge, Teller.io personal tier, direct OFX export). Plaid is only chosen if alternatives are clearly inferior for the use case. See issue #26.</li></ul><hr><h2 id="privacy-position-updated" tabindex="-1">Privacy Position (updated) <a class="header-anchor" href="#privacy-position-updated" aria-label="Permalink to &quot;Privacy Position (updated)&quot;">​</a></h2><p>The original privacy stance is preserved and strengthened, not weakened:</p><table tabindex="0"><thead><tr><th>Method</th><th>Data leaves machine?</th><th>Third party involved?</th></tr></thead><tbody><tr><td>Manual input</td><td>No</td><td>No</td></tr><tr><td>CSV import</td><td>No</td><td>No</td></tr><tr><td>Plaid (opt-in)</td><td>Plaid token exchange only</td><td>Yes — Plaid (or alternative)</td></tr></tbody></table><p>Plaid integration does involve a third-party token exchange during the OAuth flow. This is disclosed clearly in the UI. Once connected, transaction/balance data is fetched directly from the bank via Plaid and stored locally in SQLite — no Libertas cloud, no external analytics.</p><p><strong>Privacy as a feature remains front-and-center.</strong> Plaid is opt-in, clearly labeled, and the user can always use CSV or manual entry instead.</p><hr><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>The FIRE model and net worth calculation must aggregate data from all three sources cleanly</li><li>The data model needs a <code>source</code> field on accounts/balances to track origin (manual | csv | plaid)</li><li>Onboarding flow must present all three options without overwhelming new users</li><li>Legal scan (#2) must account for Plaid&#39;s data handling terms in addition to AI advice framing</li><li>ADR-001&#39;s CSV importer is unchanged; this ADR adds to it, does not replace it</li></ul><hr><h2 id="alternatives-considered" tabindex="-1">Alternatives Considered <a class="header-anchor" href="#alternatives-considered" aria-label="Permalink to &quot;Alternatives Considered&quot;">​</a></h2><p><strong>Keep CSV-only:</strong> Rejected. Too much friction for ongoing use. A financial freedom planner needs accurate, current data — weekly CSV exports are not a sustainable user behavior.</p><p><strong>Replace CSV with Plaid-only:</strong> Rejected. Breaks the privacy guarantee. Many users specifically choose Libertas <em>because</em> there&#39;s no account linking. CSV + manual must remain viable standalone paths.</p><p><strong>Manual entry only for MVP:</strong> Valid for day-one simplicity. CSV and Plaid can follow. This is the recommended MVP order: manual first, CSV already exists, Plaid after cost evaluation.</p>',35)])])}const m=a(r,[["render",o]]);export{h as __pageData,m as default};
